package main
import("context";"os";"testing";"sort";"reflect";"github.com/modelcontextprotocol/go-sdk/mcp")
func TestDesktopOnlyScopedTools(t *testing.T){
 cases:=map[string][]string{"LOGIN":{},"COLLECT":{"check_login_status","get_feed_detail","search_feeds"},"INBOX":{"inbox_start","inbox_drain","inbox_snapshot","inbox_stop"},"DM":{"workbench_dm_exact"},"PREFLIGHT":{"workbench_reply_preflight"},"VERIFY":{"workbench_reply_verify"}}
 for mode,want:=range cases{t.Run(mode,func(t *testing.T){t.Setenv("CRM_DESKTOP_MODE",mode);server:=mcp.NewServer(&mcp.Implementation{Name:"synthetic",Version:"1"},nil);registerDesktopTools(server,&AppServer{});list,e:=diagnosticSession(t,server).ListTools(context.Background(),nil);if e!=nil{t.Fatal(e)};got:=[]string{};for _,tool:=range list.Tools{got=append(got,tool.Name)};sort.Strings(got);sort.Strings(want);if !reflect.DeepEqual(got,want){t.Fatalf("mode %s tools %v",mode,got)}})}
}
func TestDesktopRoutesNeverExposeLegacyActions(t *testing.T){for _,mode:=range []string{"LOGIN","COLLECT","INBOX","DM","COMMENT","PREFLIGHT","VERIFY"}{t.Run(mode,func(t *testing.T){t.Setenv("CRM_DESKTOP_MODE",mode);app:=NewAppServer(NewXiaohongshuService(),"synthetic-loopback-token");for _,r:=range setupRoutes(app).Routes(){switch r.Path{case "/health","/mcp","/mcp/*path":case "/api/v1/login/status":if mode!="LOGIN"&&mode!="COLLECT"{t.Fatal("identity route escaped mode")};case "/api/v1/login/qrcode":if mode!="LOGIN"{t.Fatal("QR route escaped mode")};default:t.Fatalf("legacy route exposed %s",r.Path)}}})}}
func TestDesktopRequiresExplicitModeAndRejectsInheritedSendFlags(t *testing.T){t.Setenv("CRM_DESKTOP_MODE","");if desktopValidateEnvironment()==nil{t.Fatal("missing mode accepted")};t.Setenv("CRM_DESKTOP_MODE","COLLECT");t.Setenv("CRM_EXACT_REPLY_ENABLED","1");if desktopValidateEnvironment()==nil{t.Fatal("inherited send flag accepted")};os.Unsetenv("CRM_EXACT_REPLY_ENABLED");if err:=desktopValidateEnvironment();err!=nil{t.Fatal(err)}}
